-- CBRD-28069: a LEFT OUTER JOIN turned into an INNER JOIN drops the NULL-extended rows when a WHERE term can be
-- true for them through a subquery or a boolean operand
--
-- The outer-to-inner rewrite took a WHERE term as NULL-rejecting when it read the NULL-side table (wb) outside
-- NVL, CASE and the like, even inside a subquery. A subquery can still yield a row or a non-NULL value when wb
-- is NULL, and EXISTS, IN, IS NOT NULL, IS TRUE / IS FALSE, AND and OR yield FALSE or TRUE (not NULL) for a NULL
-- wb, which = 0, IS FALSE, XOR, NOT or CAST can turn into TRUE. The join now stays an outer join for such terms.
--
-- Each check compares count(*) of the query with sum(case when <same condition> then 1 else 0 end) over the
-- same outer join; the condition inside CASE is never rewritten, so it is the expected answer.
--
-- Covers:
--   - Dxx: forms that were rewritten and lost rows (OR in the subquery WHERE, COUNT / NVL / CASE / HAVING in an
--     aggregate subquery, UNION, EXISTS over an aggregate, EXISTS / IN / IS NOT NULL / IS TRUE / AND / OR used
--     as an operand of =, IS FALSE, XOR, CAST), with LEFT, RIGHT and chained outer joins
--   - Exx: forms already kept as outer joins (NOT EXISTS, NOT IN, > ALL, NVL, IS NULL, IF, CASE)
--   - Gxx: null-rejecting correlated subqueries and predicates that are still rewritten to inner joins
--   - Lxx: null-rejecting forms that now stay outer joins
--
-- D14 runs with the NO_PARALLEL_SUBQUERY hint: in client-server mode its two correlated UNION subqueries hang in
-- the shared parallel subquery job queue (the same defect as CBRD-27823), which is unrelated to this check.

drop table if exists wa, wb, wc, wd, t, u, s;
create table wa (a int, b int);
create table wb (a int, b int);
create table wc (a int);
create table wd (a int, b int);
create table t (x int, y int);
create table u (k int);
create table s (a int, b int);
insert into wa values (1, 2), (5, 3);
insert into wb values (5, 7);
insert into wc values (2), (3);
insert into wd values (5, 7);
insert into t values (2, 9), (3, 9), (3, 7);
insert into u values (7);
insert into s values (1, 1), (2, 1), (3, 9);
update statistics on wa, wb, wc, wd, t, u, s with fullscan;

select 'D01 in_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y = wb.b or t.x = wa.b)) q, (select sum(case when wc.a in (select x from t where t.y = wb.b or t.x = wa.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D02 scalar_max_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select max(x) from t where t.y = wb.b or t.x = wa.b)) q, (select sum(case when wc.a = (select max(x) from t where t.y = wb.b or t.x = wa.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D03 exists_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where exists (select 1 from t where (t.y = wb.b or t.x = wa.b) and t.x = wc.a)) q, (select sum(case when exists (select 1 from t where (t.y = wb.b or t.x = wa.b) and t.x = wc.a) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D04 count_star_eq0_jira' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from s x left outer join s y on x.a = y.b where (select count(*) from s z where z.b = y.a) = 0) q, (select sum(case when (select count(*) from s z where z.b = y.a) = 0 then 1 else 0 end) c from s x left outer join s y on x.a = y.b) o;
select 'D05 count_star_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (select count(*) from t where t.y = wb.b) = 0) q, (select sum(case when (select count(*) from t where t.y = wb.b) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D06 count_col_lt1' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (select count(t.x) from t where t.y = wb.b) < 1) q, (select sum(case when (select count(t.x) from t where t.y = wb.b) < 1 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D07 count_plus2' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select count(*) + 2 from t where t.y = wb.b)) q, (select sum(case when wc.a = (select count(*) + 2 from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D08 nvl_max_in_select_list' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select nvl(max(x), 2) from t where t.y = wb.b)) q, (select sum(case when wc.a = (select nvl(max(x), 2) from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D09 eq_any_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = any (select x from t where t.y = wb.b or t.x = wa.b)) q, (select sum(case when wc.a = any (select x from t where t.y = wb.b or t.x = wa.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D10 ge_some_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a >= some (select x from t where t.y = wb.b or t.x = wa.b)) q, (select sum(case when wc.a >= some (select x from t where t.y = wb.b or t.x = wa.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D11 exists_aggregate' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where exists (select max(x) from t where t.y = wb.b)) q, (select sum(case when exists (select max(x) from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D12 exists_is_false' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (exists (select 1 from t where t.y = wb.b)) is false) q, (select sum(case when (exists (select 1 from t where t.y = wb.b)) is false then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D13 in_is_false' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (wc.a in (select x from t where t.y = wb.b)) is false) q, (select sum(case when (wc.a in (select x from t where t.y = wb.b)) is false then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select /*+ NO_PARALLEL_SUBQUERY */ 'D14 in_union' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y = wb.b union select x from t where x = wa.b)) q, (select sum(case when wc.a in (select x from t where t.y = wb.b union select x from t where x = wa.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D15 nested_in_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y in (select t2.y from t t2 where t2.y = wb.b or t2.x = wa.b))) q, (select sum(case when wc.a in (select x from t where t.y in (select t2.y from t t2 where t2.y = wb.b or t2.x = wa.b)) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D16 nested_count_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where (select count(*) from t t2 where t2.y = wb.b) = 0)) q, (select sum(case when wc.a in (select x from t where (select count(*) from t t2 where t2.y = wb.b) = 0) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D17 right_outer_in_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wb right outer join wa on wb.a = wa.a, wc where wc.a in (select x from t where t.y = wb.b or t.x = wa.b)) q, (select sum(case when wc.a in (select x from t where t.y = wb.b or t.x = wa.b) then 1 else 0 end) c from wb right outer join wa on wb.a = wa.a, wc) o;
select 'D18 right_outer_count_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wb right outer join wa on wb.a = wa.a, wc where (select count(*) from t where t.y = wb.b) = 0) q, (select sum(case when (select count(*) from t where t.y = wb.b) = 0 then 1 else 0 end) c from wb right outer join wa on wb.a = wa.a, wc) o;
select 'D19 two_outer_in_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a left outer join wd on wd.a = wb.a, wc where wc.a in (select x from t where t.y = wd.b or t.x = wa.b)) q, (select sum(case when wc.a in (select x from t where t.y = wd.b or t.x = wa.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a left outer join wd on wd.a = wb.a, wc) o;
select 'D20 two_outer_count_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a left outer join wd on wd.a = wb.a, wc where (select count(*) from t where t.y = wd.b) = 0) q, (select sum(case when (select count(*) from t where t.y = wd.b) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a left outer join wd on wd.a = wb.a, wc) o;
select 'D22 having_count_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where exists (select 1 from t where t.y = wb.b having count(*) = 0)) q, (select sum(case when exists (select 1 from t where t.y = wb.b having count(*) = 0) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D23 scalar_limit_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select x from t where t.y = wb.b or t.x = wa.b order by x limit 1)) q, (select sum(case when wc.a = (select x from t where t.y = wb.b or t.x = wa.b order by x limit 1) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D24 count_outer_arith' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a - (select count(*) from t where t.y = wb.b) = 2) q, (select sum(case when wc.a - (select count(*) from t where t.y = wb.b) = 2 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D25 count_of_wb_in_select_list' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select 2 + count(wb.b) from t)) q, (select sum(case when wc.a in (select 2 + count(wb.b) from t) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D26 case_in_agg_select_list' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select case when max(x) is null then 2 else 0 end from t where t.y = wb.b)) q, (select sum(case when wc.a = (select case when max(x) is null then 2 else 0 end from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D27 scalar_or_no_agg' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select x from t where (t.y = wb.b or t.x = wa.b) and t.x = wc.a and t.y <> 7)) q, (select sum(case when wc.a = (select x from t where (t.y = wb.b or t.x = wa.b) and t.x = wc.a and t.y <> 7) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D28 in_or_inside_and' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.x > 0 and (t.y = wb.b or t.x = wa.b))) q, (select sum(case when wc.a in (select x from t where t.x > 0 and (t.y = wb.b or t.x = wa.b)) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D29 correlated_derived_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select d.x from (select x from t where t.y = wb.b or t.x = wa.b) d)) q, (select sum(case when wc.a in (select d.x from (select x from t where t.y = wb.b or t.x = wa.b) d) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D30 exists_xor' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (exists (select 1 from t where t.y = wb.b)) xor (wc.a = 2)) q, (select sum(case when (exists (select 1 from t where t.y = wb.b)) xor (wc.a = 2) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D31 exists_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (exists (select 1 from t where t.y = wb.b)) = 0) q, (select sum(case when (exists (select 1 from t where t.y = wb.b)) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D32 wb_in_empty_subquery_is_false' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (wb.b in (select x from t where x = 100)) is false) q, (select sum(case when (wb.b in (select x from t where x = 100)) is false then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D33 exists_one_corr_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where exists (select 1 from t where t.y = wb.b or t.x = wa.b)) q, (select sum(case when exists (select 1 from t where t.y = wb.b or t.x = wa.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D34 in_one_corr_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wa.b in (select x from t where t.y = wb.b or t.x = 2)) q, (select sum(case when wa.b in (select x from t where t.y = wb.b or t.x = 2) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D35 cast_in_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where cast((wc.a in (select x from t where t.y = wb.b)) as int) = 0) q, (select sum(case when cast((wc.a in (select x from t where t.y = wb.b)) as int) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D36 count_plus0_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (select count(*) from t where t.y = wb.b) + 0 = 0) q, (select sum(case when (select count(*) from t where t.y = wb.b) + 0 = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D37 scalar_is_not_null_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where ((select max(x) from t where t.y = wb.b) is not null) = 0) q, (select sum(case when ((select max(x) from t where t.y = wb.b) is not null) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
