select 'D40 cast_is_not_null_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where cast((wb.b is not null) as int) = 0) q, (select sum(case when cast((wb.b is not null) as int) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D41 is_not_null_is_false' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (wb.b is not null) is false) q, (select sum(case when (wb.b is not null) is false then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D42 is_true_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where ((wb.b = 7) is true) = 0) q, (select sum(case when ((wb.b = 7) is true) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D43 and_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where ((wb.b = 7) and wc.a = 3) = 0) q, (select sum(case when ((wb.b = 7) and wc.a = 3) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D44 or_eq1' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where ((wb.b = 7) or wc.a = 2) = 1) q, (select sum(case when ((wb.b = 7) or wc.a = 2) = 1 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'D45 and_is_false' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where ((wb.b = 7) and wc.a = 3) is false) q, (select sum(case when ((wb.b = 7) and wc.a = 3) is false then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
