select 'E03 gt_all' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a > all (select x from t where t.y = wb.b)) q, (select sum(case when wc.a > all (select x from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'E04 nvl_scalar' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where nvl((select x from t where t.y = wb.b), 2) = wc.a) q, (select sum(case when nvl((select x from t where t.y = wb.b), 2) = wc.a then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'E05 nvl_wb_in_select_list' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select nvl(wb.b, 2) from t where t.x = 2)) q, (select sum(case when wc.a = (select nvl(wb.b, 2) from t where t.x = 2) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'E06 sum_is_null' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (select sum(x) from t where t.y = wb.b) is null) q, (select sum(case when (select sum(x) from t where t.y = wb.b) is null then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'E07 coalesce_sum' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where coalesce((select sum(x) from t where t.y = wb.b), 0) = 0) q, (select sum(case when coalesce((select sum(x) from t where t.y = wb.b), 0) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'E08 or_at_term_level' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y = wb.b) or wc.a = 2) q, (select sum(case when wc.a in (select x from t where t.y = wb.b) or wc.a = 2 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'E09 exists_wb_in_select_list' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where exists (select wb.b from t where t.x = wc.a)) q, (select sum(case when exists (select wb.b from t where t.x = wc.a) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'E10 if_exists_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where if(exists (select 1 from t where t.y = wb.b), 1, 0) = 0) q, (select sum(case when if(exists (select 1 from t where t.y = wb.b), 1, 0) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'E11 case_exists_eq0' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (case when exists (select 1 from t where t.y = wb.b) then 1 else 0 end) = 0) q, (select sum(case when (case when exists (select 1 from t where t.y = wb.b) then 1 else 0 end) = 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G01 in' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y = wb.b)) q, (select sum(case when wc.a in (select x from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G02 exists_two_corr' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where exists (select 1 from t where t.y = wb.b and t.x = wc.a)) q, (select sum(case when exists (select 1 from t where t.y = wb.b and t.x = wc.a) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G03 scalar_max' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select max(x) from t where t.y = wb.b)) q, (select sum(case when wc.a = (select max(x) from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G04 eq_any' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = any (select x from t where t.y = wb.b)) q, (select sum(case when wc.a = any (select x from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G05 scalar_sum' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select sum(x) from t where t.y = wb.b)) q, (select sum(case when wc.a = (select sum(x) from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G06 scalar_min' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select min(x) from t where t.y = wb.b)) q, (select sum(case when wc.a = (select min(x) from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G07 scalar_avg' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select avg(x) from t where t.y = wb.b)) q, (select sum(case when wc.a = (select avg(x) from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G08 scalar_no_agg' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select x from t where t.y = wb.b)) q, (select sum(case when wc.a = (select x from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G09 count_group_by' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where 1 = (select count(*) from t where t.y = wb.b group by t.y)) q, (select sum(case when 1 = (select count(*) from t where t.y = wb.b group by t.y) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G10 in_and_or_without_wb' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y = wb.b and (t.x = 3 or t.x = wa.b))) q, (select sum(case when wc.a in (select x from t where t.y = wb.b and (t.x = 3 or t.x = wa.b)) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G11 in_and_or_with_wb' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y = wb.b and (t.x = wb.a - 2 or t.x = wa.b))) q, (select sum(case when wc.a in (select x from t where t.y = wb.b and (t.x = wb.a - 2 or t.x = wa.b)) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G12 right_outer_in' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wb right outer join wa on wb.a = wa.a, wc where wc.a in (select x from t where t.y = wb.b)) q, (select sum(case when wc.a in (select x from t where t.y = wb.b) then 1 else 0 end) c from wb right outer join wa on wb.a = wa.a, wc) o;
select 'G13 two_outer_in' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a left outer join wd on wd.a = wb.a, wc where wc.a in (select x from t where t.y = wd.b)) q, (select sum(case when wc.a in (select x from t where t.y = wd.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a left outer join wd on wd.a = wb.a, wc) o;
select 'G14 wb_in_select_and_where' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select wb.a - 2 from t where t.y = wb.b)) q, (select sum(case when wc.a in (select wb.a - 2 from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G15 plain_compare' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wb.b = 7) q, (select sum(case when wb.b = 7 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G16 plain_join_compare' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = wb.b - 4) q, (select sum(case when wc.a = wb.b - 4 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G17 exists_one_corr' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where exists (select 1 from t where t.y = wb.b)) q, (select sum(case when exists (select 1 from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G18 scalar_max_outer_arith' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select max(x) from t where t.y = wb.b) + 0) q, (select sum(case when wc.a = (select max(x) from t where t.y = wb.b) + 0 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G19 in_between' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y between wb.b and wb.b + 1)) q, (select sum(case when wc.a in (select x from t where t.y between wb.b and wb.b + 1) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G20 nested_in' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y in (select t2.y from t t2 where t2.y = wb.b))) q, (select sum(case when wc.a in (select x from t where t.y in (select t2.y from t t2 where t2.y = wb.b)) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G21 count_star_eq1_jira_tables' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from s x left outer join s y on x.a = y.b where (select max(z.a) from s z where z.b = y.a) = 2) q, (select sum(case when (select max(z.a) from s z where z.b = y.a) = 2 then 1 else 0 end) c from s x left outer join s y on x.a = y.b) o;
select 'G22 in_one_corr' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wa.b in (select x from t where t.y = wb.b)) q, (select sum(case when wa.b in (select x from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G23 column_is_not_null' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wb.b is not null) q, (select sum(case when wb.b is not null then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'G24 is_true_root' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where (wb.b = 7) is true) q, (select sum(case when (wb.b = 7) is true then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'L01 wb_only_in_select_list' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select wb.b - 4 from t where t.x = 2)) q, (select sum(case when wc.a = (select wb.b - 4 from t where t.x = 2) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'L02 agg_inside_arith' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select max(x) + 0 from t where t.y = wb.b)) q, (select sum(case when wc.a = (select max(x) + 0 from t where t.y = wb.b) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'L03 correlated_derived_rejecting' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select d.x from (select x from t where t.y = wb.b) d)) q, (select sum(case when wc.a in (select d.x from (select x from t where t.y = wb.b) d) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'L04 max_of_wb' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a = (select max(wb.b) - 4 from t)) q, (select sum(case when wc.a = (select max(wb.b) - 4 from t) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'L05 rejecting_and_nested_or' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where wc.a in (select x from t where t.y = wb.b and exists (select 1 from u where u.k = wb.b or u.k = t.x))) q, (select sum(case when wc.a in (select x from t where t.y = wb.b and exists (select 1 from u where u.k = wb.b or u.k = t.x)) then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;
select 'L06 is_true_eq1' as chk, if (q.c = o.c, 'PASS', 'FAIL') as res from (select count(*) c from wa left outer join wb on wb.a = wa.a, wc where ((wb.b = 7) is true) = 1) q, (select sum(case when ((wb.b = 7) is true) = 1 then 1 else 0 end) c from wa left outer join wb on wb.a = wa.a, wc) o;

drop table if exists wa, wb, wc, wd, t, u, s;
